import pandas as pd
import numpy as np

def maximize_items(inventory: pd.DataFrame) -> pd.DataFrame:
    prime = inventory[inventory['item_type'] == 'prime_eligible']
    not_prime = inventory[inventory['item_type'] == 'not_prime']

    prime_s = prime['square_footage'].sum() if not prime.empty else 0
    prime_cnt = len(prime)

    if prime_s > 0:
        prime_batches = 500000 // prime_s
        prime_items = int(prime_cnt * prime_batches)
        rem_space = 500000 % prime_s
    else:
        prime_items = 0
        rem_space = 500000

    np_s = not_prime['square_footage'].sum() if not not_prime.empty else 0
    np_cnt = len(not_prime)

    if np_s > 0:
        np_batches = rem_space // np_s
        np_items = int(np_cnt * np_batches)
    else:
        np_items = 0

    res = pd.DataFrame([
        {'item_type': 'prime_eligible', 'item_count': prime_items},
        {'item_type': 'not_prime', 'item_count': np_items}
    ])
    return res.sort_values(by=['item_count', 'item_type'], ascending=[False, False])
